from typing import List, Tuple
import re
from collections import Counter

def majority_vote_answers(candidates: List[str]) -> Tuple[str, float]:
    extracted = []
    for c in candidates:
        m = re.search(r'答案:\s*(\d+)', c)
        if m:
            extracted.append(m.group(1))
    if not extracted:
        return ("", 0.0)
    counts = Counter(extracted)
    winner, count = counts.most_common(1)[0]
    conf = round(count / len(extracted), 2)
    return (winner, conf)

samples = [
    "计算过程很长，答案: 42",
    "逐步推导如下，答案: 42",
    "算错了，答案: 10",
    "严格证明，答案: 42"
]
res = majority_vote_answers(samples)
print(res)

